package add_parameter

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/generated/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "add_parameter"
	command.Identifiers = []string{"add-parameter"}
	command.Category = "Server System"
	command.Help = "Declare one value a route reads from the query string or the headers"
	command.LongDescription = "Declares one value a route reads and runs build so the route's new.go and entries.go pick it up. It is read under its name from the first of its --font that brings it, converted to its --type and bound to Entries.<Name>; a missing --required one is answered 400 before the handler runs, and one with a --trigger only lets the route run when it matches."
	command.Examples = []string{"add-parameter page --route list-users --type number --default 1", "add-parameter authorization --route admin --font header --trigger Bearer --trigger-type prefix"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route (identifier or package name) that receives the parameter",
			Examples:    []string{"add-parameter page --route list-users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--route"},
		},
		{
			Id:          "type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the value type: string, integer, number, boolean, datetime, string-array or integer-array (defaults to string)",
			Examples:    []string{"add-parameter page --route list-users --type integer"},
			Default:     "string",
			HasDefault:  true,
			Identifiers: []string{"--type"},
		},
		{
			Id:          "font",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "where the value is read from, in order: query, header or cookie (repeatable; defaults to query)",
			Examples:    []string{"add-parameter session --route admin --font cookie"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--font"},
		},
		{
			Id:          "required",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "answer 400 when no font brings the value (not for booleans or parameters with --default)",
			Examples:    []string{"add-parameter q --route search --required"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--required"},
		},
		{
			Id:          "default",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the literal bound when no font brings the value (cannot be combined with --required)",
			Examples:    []string{"add-parameter page --route list-users --type number --default 1"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--default"},
		},
		{
			Id:          "trigger",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "what the value has to match for the route to run at all, putting the parameter into what the route matches on",
			Examples:    []string{"add-parameter authorization --route admin --font header --trigger Bearer --trigger-type prefix"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger"},
		},
		{
			Id:          "trigger-type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "how the trigger is compared: equal, prefix, text-prefix, suffix or regex — or starts-with, ends-with, exact, matches (defaults to equal; on a value, prefix and text-prefix are the same)",
			Examples:    []string{"add-parameter authorization --route admin --font header --trigger Bearer --trigger-type prefix"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-type"},
		},
		{
			Id:          "trigger-negate",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "invert the trigger: the route runs when the value does not match it",
			Examples:    []string{"add-parameter authorization --route public --font header --trigger Bearer --trigger-type prefix --trigger-negate"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-negate"},
		},
		{
			Id:          "trigger-ignore-case",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "compare the trigger without regard to case",
			Examples:    []string{"add-parameter authorization --route admin --font header --trigger bearer --trigger-type prefix --trigger-ignore-case"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-ignore-case"},
		},
		{
			Id:          "description",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "help text shown for the parameter",
			Examples:    []string{"add-parameter page --route list-users --description 'the page to read'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--description"},
		},
		{
			Id:          "example",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "an usage example for the parameter (repeatable)",
			Examples:    []string{"add-parameter page --route list-users --example '?page=2'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--example"},
		},
		{
			Id:          "position",
			Type:        "int",
			Required:    false,
			Array:       false,
			Description: "zero-based index to insert the parameter at (defaults to the end)",
			Examples:    []string{"add-parameter page --route list-users --position 0"},
			Default:     "-1",
			HasDefault:  true,
			Identifiers: []string{"--position"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"add-parameter page --route list-users --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the query key or header name it is read under; its Entries field is the exported spelling of it",
			Examples:    []string{"add-parameter page --route list-users --type number"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
